class Solution { public: int checkRecord(int n){const long long mod=1000000007;long long dp[2][3]={{1,0,0},{0,0,0}};while(n--){long long next[2][3]{};for(int a=0;a<2;++a)for(int l=0;l<3;++l){long long value=dp[a][l];next[a][0]=(next[a][0]+value)%mod;if(a==0)next[1][0]=(next[1][0]+value)%mod;if(l<2)next[a][l+1]=(next[a][l+1]+value)%mod;}copy(&next[0][0],&next[0][0]+6,&dp[0][0]);}long long answer=0;for(auto& row:dp)for(long long value:row)answer=(answer+value)%mod;return answer;} };
